// VERBEX · II3 · Construir body para Anthropic API
// Contiene el system prompt completo (SOUL + SKILL condensados con 5 ejemplos few-shot).
// Salida: objeto JSON listo para enviar como body a /v1/messages.

const SYSTEM_PROMPT = `Eres el agente de normalización de Purchase Orders de VERBEX COMPOSITES S.L. (Tier 2 composites, Sevilla). Recibes POs en texto libre de clientes Tier 1 (Stratos, Kairos) y OEMs (Helion, Vectair).

REGLAS ABSOLUTAS:
1. Nunca calculas fechas, días ni cantidades. Solo extraes lo escrito.
2. Nunca inventas Part Numbers. Si no reconoces un PN, part_number_proveedor: null y bajas la confianza.
3. Si detectas AOG, "Aircraft on Ground", "inmovilizado" o urgencia extrema, devuelves "aog": true.
4. Si el texto menciona "Rev.", "Amendment", añades alerta con numero_pedido original.
5. Devuelves SOLO el JSON. Sin explicaciones, sin markdown.
6. El idioma de los campos extraídos es el del documento original.
7. prioridad SIEMPRE "NORMAL" — n8n recalcula con R01/R02.

CLIENTES (nombre → codigo_erp · tier · programa):
- Stratos Systems → STRA-001 · TIER_1 · ST900
- Kairos Aerospace → KAIRO-001 · TIER_1 · HX7
- Kairos Defense → KAIRO-002 · TIER_1 · HX7
- Helion Aircraft → HELI-001 · OEM · HX7
- Vectair Industries Iberia → VECT-001 · OEM · VX4

EQUIVALENCIAS PN cliente → PN proveedor:
ST9-HTP-RIB-047 → VBX-COMP-4471-B (Costilla HTP delantera, ST900, CoC)
ST9-HTP-RIB-048 → VBX-COMP-4472-C (Costilla HTP trasera, ST900, CoC)
HX7-FUS-PNL-331 → VBX-COMP-3301-A (Panel fuselaje central, HX7, CoC + EASA Form 1)
HX7-FUS-PNL-332 → VBX-COMP-3302-A (Panel fuselaje lateral, HX7, CoC + EASA Form 1)
HX7-BHD-332 → VBX-COMP-3303-B (Mamparo, HX7, CoC + EASA Form 1)
ST9-LE-PNL-550 → VBX-COMP-5501-A (Borde ataque ala, ST900, CoC)
HX7-ELV-220 → VBX-COMP-2201-C (Timón, RT55, CoC + EASA Form 1)

Si PN cliente NO en tabla: part_number_proveedor: null + confianza baja.

UNIDADES VÁLIDAS: EA | KG | ML | M2.

CONFIANZA:
0.95+ → texto estructurado (HelionLink CSV)
0.80-0.95 → texto libre estándar
0.60-0.80 → algún PN desconocido o campo ambiguo
< 0.60 → varios campos faltantes

SCHEMA estricto:
{"numero_pedido":string,"cliente":{"nombre":string|null,"tier":TIER_1|OEM|null,"codigo_erp":string|null},"lineas":[{"linea_id":N,"part_number_cliente":string,"part_number_proveedor":string|null,"descripcion":string,"cantidad":N,"unidad":EA|KG|ML|M2,"precio_unitario":null,"fecha_entrega_requerida":YYYY-MM-DD|null,"programa":HX7|ST900|RT55|VX4|OTRO,"prioridad":NORMAL,"requiere_coc":bool,"requiere_easa_form1":bool}],"estado_normalizacion":COMPLETO|PARCIAL|ERROR,"confianza":0.0-1.0,"alertas":[string],"aog":bool}

NO PO: {"error":"no_pedido","mensaje":"descripción"}

EJEMPLOS:

E1) INPUT: Purchase Order PO-2025-STRA-0847. Stratos Systems. Part: ST9-HTP-RIB-047, Qty: 12 EA, Need Date: 15/09/2025. Ref: ST-900 program. CoC required.
OUTPUT: {"numero_pedido":"PO-2025-STRA-0847","cliente":{"nombre":"Stratos Systems","tier":"TIER_1","codigo_erp":"STRA-001"},"lineas":[{"linea_id":1,"part_number_cliente":"ST9-HTP-RIB-047","part_number_proveedor":"VBX-COMP-4471-B","descripcion":"Costilla composite HTP sección delantera","cantidad":12,"unidad":"EA","precio_unitario":null,"fecha_entrega_requerida":"2025-09-15","programa":"ST900","prioridad":"NORMAL","requiere_coc":true,"requiere_easa_form1":false}],"estado_normalizacion":"COMPLETO","confianza":0.97,"alertas":[],"aog":false}

E2) INPUT: HELIONLINK|HX7-FUS-PNL-331|24|EA|2025-10-01|HX7|KAIRO-001|Normal
OUTPUT: {"numero_pedido":"HELIONLINK-HX7-FUS-PNL-331-2025-10-01","cliente":{"nombre":"Kairos Aerospace","tier":"TIER_1","codigo_erp":"KAIRO-001"},"lineas":[{"linea_id":1,"part_number_cliente":"HX7-FUS-PNL-331","part_number_proveedor":"VBX-COMP-3301-A","descripcion":"Panel fuselaje composite sección central HX-7","cantidad":24,"unidad":"EA","precio_unitario":null,"fecha_entrega_requerida":"2025-10-01","programa":"HX7","prioridad":"NORMAL","requiere_coc":true,"requiere_easa_form1":true}],"estado_normalizacion":"COMPLETO","confianza":0.99,"alertas":[],"aog":false}

E3) INPUT: URGENT AOG - EC-MKL inmovilizado Aeropuerto Sevilla. Necesitamos HX7-FUS-PNL-332 x2 inmediatamente. Contacto: Juan García 654321098
OUTPUT: {"numero_pedido":"AOG-EC-MKL-PNL-332","cliente":{"nombre":null,"tier":null,"codigo_erp":null},"lineas":[{"linea_id":1,"part_number_cliente":"HX7-FUS-PNL-332","part_number_proveedor":"VBX-COMP-3302-A","descripcion":"Panel fuselaje composite sección lateral HX-7","cantidad":2,"unidad":"EA","precio_unitario":null,"fecha_entrega_requerida":null,"programa":"HX7","prioridad":"NORMAL","requiere_coc":true,"requiere_easa_form1":true}],"estado_normalizacion":"PARCIAL","confianza":0.85,"alertas":["AOG detectado - verificar stock inmediatamente","Cliente no identificado - contacto Juan García 654321098"],"aog":true}

E4) INPUT: PO-2025-STRA-0847 Rev. B. Amendment: cantidad línea 1 cambia de 12 a 8 EA. Nueva Need Date: 30/09/2025.
OUTPUT: {"numero_pedido":"PO-2025-STRA-0847-RevB","cliente":{"nombre":"Stratos Systems","tier":"TIER_1","codigo_erp":"STRA-001"},"lineas":[{"linea_id":1,"part_number_cliente":"ST9-HTP-RIB-047","part_number_proveedor":"VBX-COMP-4471-B","descripcion":"Costilla composite HTP sección delantera","cantidad":8,"unidad":"EA","precio_unitario":null,"fecha_entrega_requerida":"2025-09-30","programa":"ST900","prioridad":"NORMAL","requiere_coc":true,"requiere_easa_form1":false}],"estado_normalizacion":"COMPLETO","confianza":0.94,"alertas":["Amendment - revisar PO original PO-2025-STRA-0847 Rev. A"],"aog":false}

E5) INPUT: Pedido 5521. Componente ST9-HTP-RIB-999 x4 EA. Entrega: 01/11/2025.
OUTPUT: {"numero_pedido":"5521","cliente":{"nombre":null,"tier":null,"codigo_erp":null},"lineas":[{"linea_id":1,"part_number_cliente":"ST9-HTP-RIB-999","part_number_proveedor":null,"descripcion":"PN no encontrado en tabla de equivalencias","cantidad":4,"unidad":"EA","precio_unitario":null,"fecha_entrega_requerida":"2025-11-01","programa":"ST900","prioridad":"NORMAL","requiere_coc":false,"requiere_easa_form1":false}],"estado_normalizacion":"PARCIAL","confianza":0.60,"alertas":["PN cliente ST9-HTP-RIB-999 no encontrado en tabla de equivalencias","Cliente no identificado"],"aog":false}

DEVUELVE SOLO EL JSON. NADA MÁS.`;

//const texto = $input.item.json.texto_po || '';

const texto = `
Purchase Order PO-2025-STRA-0847. Stratos Systems.
Part: ST9-HTP-RIB-047, Qty: 12 EA, Need Date: 15/09/2025.
Ref: ST-900 program. CoC required.
`

return [{
  json: {
    model: 'claude-sonnet-4-20250514',
    max_tokens: 1500,
    temperature: 0.1,
    system: SYSTEM_PROMPT,
    messages: [
      { role: 'user', content: `Texto de la PO a normalizar:\n\n${texto}` }
    ]
  }
}];

// VERBEX · II3 · Validar JSON LLM (parser anti-alucinación)
// 1. Extrae bloque JSON (limpia code fences si los hay)
// 2. Valida schema mínimo (lineas[] no vacío)
// 3. Verifica que part_number_proveedor citado por el LLM exista en catálogo;
//    si el LLM inventa un PN, lo fuerza a null y añade alerta.

const PNS_VALIDOS = new Set([
  'VBX-COMP-4471-B','VBX-COMP-4472-C','VBX-COMP-3301-A','VBX-COMP-3302-A',
  'VBX-COMP-3303-B','VBX-COMP-5501-A','VBX-COMP-5502-A','VBX-COMP-2201-C',
  'VBX-COMP-2202-C','VBX-COMP-6601-A','VBX-COMP-6602-A','VBX-COMP-7701-B',
  'VBX-COMP-7702-B','VBX-COMP-8801-A','VBX-COMP-9901-A','VBX-COMP-9902-A'
]);

const apiResp = $input.item.json;
if (!apiResp.content || !apiResp.content[0]) {
  throw new Error('LLM_API_ERROR: respuesta vacía de Claude API');
}

const raw = apiResp.content[0].text.trim();
const clean = raw.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();

let po;
try {
  po = JSON.parse(clean);
} catch (e) {
  throw new Error(`JSON_PARSE_ERROR: ${e.message} | Raw: ${clean.substring(0, 300)}`);
}

if (po.error === 'no_pedido') {
  return [{
    json: {
      ...po,
      estado_normalizacion: 'ERROR',
      alertas: [`LLM clasificó como no_pedido: ${po.mensaje || ''}`],
      lineas: [],
      aog: false,
      confianza: 0
    }
  }];
}

if (!po.lineas || !Array.isArray(po.lineas) || po.lineas.length === 0) {
  throw new Error('SCHEMA_ERROR: lineas[] vacío o ausente en respuesta del LLM');
}

const alertas = [...(po.alertas || [])];
for (const linea of po.lineas) {
  if (linea.part_number_proveedor && !PNS_VALIDOS.has(linea.part_number_proveedor)) {
    alertas.push(`PARSER: PN proveedor inventado por el LLM en línea ${linea.linea_id}: ${linea.part_number_proveedor}. Forzado a null.`);
    linea.part_number_proveedor = null;
  }
}
po.alertas = alertas;

return [{ json: po }];

// VERBEX · II3 · R04 + R08 · Validar catálogo y cantidades
const EQUIVALENCIAS_PN = {
  'ST9-HTP-RIB-047': 'VBX-COMP-4471-B',
  'ST9-HTP-RIB-048': 'VBX-COMP-4472-C',
  'HX7-FUS-PNL-331': 'VBX-COMP-3301-A',
  'HX7-FUS-PNL-332': 'VBX-COMP-3302-A',
  'HX7-BHD-332':     'VBX-COMP-3303-B',
  'ST9-LE-PNL-550':  'VBX-COMP-5501-A',
  'HX7-ELV-220':     'VBX-COMP-2201-C'
};
const UNIDADES_VALIDAS = ['EA', 'KG', 'ML', 'M2'];

const po = JSON.parse(JSON.stringify($input.item.json));
const alertas = [...(po.alertas || [])];
let estadoError = false;

for (const linea of po.lineas) {
  if (!EQUIVALENCIAS_PN[linea.part_number_cliente]) {
    alertas.push(`R04: PN cliente desconocido en línea ${linea.linea_id}: ${linea.part_number_cliente}`);
    estadoError = true;
  }
  if (linea.cantidad <= 0) {
    alertas.push(`R08: cantidad inválida en línea ${linea.linea_id}: ${linea.cantidad}`);
    estadoError = true;
  }
  if (!UNIDADES_VALIDAS.includes(linea.unidad)) {
    alertas.push(`R08: unidad no reconocida en línea ${linea.linea_id}: ${linea.unidad}`);
    estadoError = true;
  }
}

if (estadoError) po.estado_normalizacion = 'ERROR';
po.alertas = alertas;
return [{ json: po }];

// VERBEX · II3 · R07 · Verificar cliente registrado
const CLIENTES_REGISTRADOS = ['STRA-001', 'KAIRO-001', 'KAIRO-002', 'HELI-001', 'VECT-001'];

const po = JSON.parse(JSON.stringify($input.item.json));
const alertas = [...(po.alertas || [])];

const codErp = po.cliente?.codigo_erp;
if (!codErp || !CLIENTES_REGISTRADOS.includes(codErp)) {
  alertas.push(`R07: cliente no registrado (codigo_erp: ${codErp || 'null'}). Pipeline continúa con flag.`);
  if (po.estado_normalizacion === 'COMPLETO') {
    po.estado_normalizacion = 'PARCIAL';
  }
  po.cliente_no_registrado = true;
} else {
  po.cliente_no_registrado = false;
}

po.alertas = alertas;
return [{ json: po }];

// VERBEX · II3 · R01 + R02 · Aplicar urgencia
const po = JSON.parse(JSON.stringify($input.item.json));
const alertas = [...(po.alertas || [])];

const hoy = new Date();
hoy.setHours(0, 0, 0, 0);

let prioridadGlobal = 'NORMAL';

if (po.aog) {
  prioridadGlobal = 'AOG';
  alertas.push('R01: AOG detectado, prioridad escalada a AOG');
}

for (const linea of po.lineas) {
  if (po.aog) {
    linea.prioridad = 'AOG';
    continue;
  }
  if (linea.fecha_entrega_requerida) {
    const fechaEntrega = new Date(linea.fecha_entrega_requerida);
    const diffDias = Math.ceil((fechaEntrega - hoy) / (1000 * 60 * 60 * 24));
    if (diffDias <= 7 && diffDias >= 0) {
      linea.prioridad = 'PRIORITARIO';
      if (prioridadGlobal === 'NORMAL') prioridadGlobal = 'PRIORITARIO';
      alertas.push(`R02: línea ${linea.linea_id} a ${diffDias} días, prioridad PRIORITARIO`);
    }
  }
}

po.prioridad_calculada = prioridadGlobal;
po.alertas = alertas;
return [{ json: po }];

// VERBEX · II3 · R05 + R06 · Asignar certificaciones
const po = JSON.parse(JSON.stringify($input.item.json));

for (const linea of po.lineas) {
  const docs = [];
  if (linea.requiere_coc) docs.push('CoC');
  if (linea.requiere_easa_form1) docs.push('EASA Form 1');
  if (docs.length) linea.doc_requerida = docs;
}

return [{ json: po }];

// VERBEX · II3 · R03 · Aplicar confianza umbral
const po = JSON.parse(JSON.stringify($input.item.json));
const alertas = [...(po.alertas || [])];

if (typeof po.confianza === 'number' && po.confianza < 0.80) {
  if (po.estado_normalizacion === 'COMPLETO') {
    po.estado_normalizacion = 'PARCIAL';
  }
  alertas.push(`R03: confianza baja (${po.confianza.toFixed(2)} < 0.80), revisar manualmente`);
}

po.alertas = alertas;
return [{ json: po }];

// VERBEX · II3 · R09 · Stub anti-spam
const PEDIDOS_YA_PROCESADOS = new Set(['PO-2025-STRA-9999']);

const po = JSON.parse(JSON.stringify($input.item.json));
const alertas = [...(po.alertas || [])];

if (PEDIDOS_YA_PROCESADOS.has(po.numero_pedido)) {
  alertas.push(`R09: ${po.numero_pedido} ya procesado previamente. Marcado como duplicado, no se reenvía.`);
  po.duplicado = true;
} else {
  po.duplicado = false;
}

po.alertas = alertas;
return [{ json: po }];
